import { memo, useState } from 'react';
import { pageToSvg, type LaidOutDocument, type Page } from '../../worksheet';

const PageView = memo(function PageView({ page, label }: { page: Page; label: string }) {
  return (
    <div
      className="page"
      role="img"
      aria-label={label}
      style={{ aspectRatio: `${page.width} / ${page.height}` }}
      // The markup is generated by our own layout code and all text is XML-escaped.
      dangerouslySetInnerHTML={{ __html: pageToSvg(page) }}
    />
  );
});

type Tab = 'worksheet' | 'answers';

interface Props {
  readonly document: LaidOutDocument;
  readonly updating: boolean;
}

export function Preview({ document, updating }: Props) {
  const [tab, setTab] = useState<Tab>('worksheet');
  const pages = tab === 'worksheet' ? document.worksheet : document.answers;
  const name = tab === 'worksheet' ? 'Worksheet' : 'Answer key';

  return (
    <div className="preview">
      <div className="tabs" role="tablist" aria-label="Preview">
        {(['worksheet', 'answers'] as const).map((value) => {
          const count = document[value].length;
          return (
            <button
              key={value}
              type="button"
              role="tab"
              id={`tab-${value}`}
              aria-selected={tab === value}
              aria-controls="preview-pages"
              className="tab"
              onClick={() => {
                setTab(value);
              }}
            >
              {value === 'worksheet' ? 'Worksheet' : 'Answer key'}
              <span className="tab__count">
                {count} {count === 1 ? 'page' : 'pages'}
              </span>
            </button>
          );
        })}
      </div>
      <div
        id="preview-pages"
        role="tabpanel"
        aria-labelledby={`tab-${tab}`}
        aria-busy={updating}
        className={`preview__pages${updating ? ' preview__pages--updating' : ''}`}
      >
        {pages.map((page, i) => (
          <PageView key={i} page={page} label={`${name}, page ${i + 1} of ${pages.length}`} />
        ))}
      </div>
    </div>
  );
}
